create or replace view public.frescura_diario_sku with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Diario SKU';
grant select on public.frescura_diario_sku to authenticated;

create or replace view public.frescura_resumen with (security_invoker = true) as
select f.numero_fila, f.celdas from public.frescura_filas f join public.frescura_hojas h on h.id=f.hoja_id where h.nombre='Resumen';
grant select on public.frescura_resumen to authenticated;

